-- PREPARED ONLY: requires ambulatory_nutrition_validation.sql before any new request.
-- G-01..G-12 nutrition/elimination lifecycle. Do not apply without real PostgreSQL/RLS/SDK compatibility testing.
create schema if not exists care_private;
revoke all on schema care_private from public,anon;
grant usage on schema care_private to authenticated;
create table if not exists public.nutrition_elimination_plan_bindings(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),client_id uuid not null references public.clients(id),
 plan_version_id uuid not null,measure_id uuid not null references public.care_plan_items(id),visit_id uuid not null references public.care_tour_stops(id),assessment_id uuid not null,
 kind text not null check(kind in('nutrition_assessment','meal_support','drink_protocol','swallowing_support','enteral_nutrition','fluid_balance','continence_support','stool_protocol','catheter_care','stoma_care','tube_observation','weight_followup')),
 title text not null check(btrim(title)<>''),planned_at timestamptz not null,plan_snapshot_sha256 text not null check(plan_snapshot_sha256~'^sha256:[0-9a-f]{64}$'),
 source_originals jsonb not null,plan_original jsonb not null,created_at timestamptz not null default clock_timestamp(),unique(tenant_id,client_id,plan_version_id,measure_id,visit_id,kind)
);
create table if not exists public.nutrition_elimination_roots(id uuid primary key,tenant_id uuid not null references public.tenants(id),client_id uuid not null references public.clients(id),kind text not null,plan_binding_id uuid not null references public.nutrition_elimination_plan_bindings(id),created_at timestamptz not null,unique(id,tenant_id,client_id));
create table if not exists public.nutrition_elimination_events(
 id uuid primary key,tenant_id uuid not null,client_id uuid not null,root_id uuid not null,revision integer not null check(revision>0),previous_id uuid,request_id uuid not null,actor_id uuid not null references public.profiles(id),actor_name text not null check(btrim(actor_name)<>''),recorded_at timestamptz not null,reason text not null,payload jsonb not null,content_fingerprint text not null check(content_fingerprint~'^sha256:[0-9a-f]{64}$'),packet jsonb not null,
 unique(root_id,revision),unique(tenant_id,request_id),unique(id,root_id),foreign key(root_id,tenant_id,client_id) references public.nutrition_elimination_roots(id,tenant_id,client_id),foreign key(previous_id,root_id) references public.nutrition_elimination_events(id,root_id),check((revision=1)=(previous_id is null))
);
create table if not exists public.nutrition_elimination_receipts(request_id uuid primary key,tenant_id uuid not null,client_id uuid not null,actor_id uuid not null,root_id uuid not null,event_id uuid not null,packet jsonb not null,original jsonb not null,recorded_at timestamptz not null,foreign key(event_id,root_id) references public.nutrition_elimination_events(id,root_id));
create index if not exists nutrition_elimination_scope on public.nutrition_elimination_roots(tenant_id,client_id,created_at desc,id desc);
alter table public.nutrition_elimination_plan_bindings enable row level security;alter table public.nutrition_elimination_roots enable row level security;alter table public.nutrition_elimination_events enable row level security;alter table public.nutrition_elimination_receipts enable row level security;
revoke all on public.nutrition_elimination_plan_bindings,public.nutrition_elimination_roots,public.nutrition_elimination_events,public.nutrition_elimination_receipts from public,anon,authenticated;

create or replace function care_private.nutrition_elimination_actor(requested_tenant uuid,requested_client uuid,requested_actor uuid,write_access boolean)
returns uuid language plpgsql security definer set search_path='' as $$declare t uuid:=public.current_tenant_id();session_user uuid:=auth.uid();actor uuid:=public.resolve_current_profile_id();profile_count integer;begin
 if t is null or t<>requested_tenant or session_user is null or actor is null or actor<>requested_actor then raise exception 'Keine aktuelle Berechtigung.' using errcode='42501';end if;
 if not exists(select 1 from auth.sessions s where s.id=(auth.jwt()->>'session_id')::uuid and s.user_id=session_user and (s.not_after is null or s.not_after>clock_timestamp())) or coalesce((auth.jwt()->>'exp')::bigint,0)<=extract(epoch from clock_timestamp())::bigint then raise exception 'Sitzung ist abgelaufen.' using errcode='42501';end if;
 select count(*) into profile_count from public.profiles p where p.id=actor and p.tenant_id=t and coalesce(p.is_active,true)=true;
 if profile_count<>1 or not public.is_active_pfleger_client(requested_client) or not public.has_permission('pflege.plans.view') or not public.has_permission('pflege.documentation.view') or write_access and not public.has_permission('pflege.documentation.create') then raise exception 'Keine aktuelle Berechtigung.' using errcode='42501';end if;return actor;end$$;

create or replace function care_private.nutrition_elimination_original(root_ref uuid)
returns jsonb language sql security definer set search_path='' stable as $$select jsonb_build_object('id',h.id::text,'tenantId',r.tenant_id::text,'clientId',r.client_id::text,'rootId',r.id::text,'headId',h.id::text,'revision',h.revision,'kind',r.kind,'recordedAt',to_char(h.recorded_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'recordedBy',h.actor_id::text,'recordedByName',h.actor_name,'payload',h.payload,'contentFingerprint',h.content_fingerprint,'history',(select jsonb_agg(jsonb_build_object('id',e.id::text,'revision',e.revision,'previousId',case when e.previous_id is null then null else e.previous_id::text end,'recordedAt',to_char(e.recorded_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'recordedBy',e.actor_id::text,'recordedByName',e.actor_name,'reason',e.reason,'payload',e.payload,'contentFingerprint',e.content_fingerprint) order by e.revision) from public.nutrition_elimination_events e where e.root_id=r.id),'voided',false) from public.nutrition_elimination_roots r join lateral(select e.* from public.nutrition_elimination_events e where e.root_id=r.id order by e.revision desc limit 1)h on true where r.id=root_ref$$;

create or replace function care_private.read_nutrition_elimination_prerequisites(requested_tenant uuid,requested_client uuid,requested_actor uuid)
returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;begin perform care_private.nutrition_elimination_actor(requested_tenant,requested_client,requested_actor,false);select jsonb_build_object('plans',coalesce(jsonb_agg(jsonb_build_object('planVersionId',b.plan_version_id::text,'measureId',b.measure_id::text,'visitId',b.visit_id::text,'assessmentId',b.assessment_id::text,'planSnapshotSha256',b.plan_snapshot_sha256,'kind',b.kind,'title',b.title,'plannedAt',to_char(b.planned_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'sources',b.source_originals) order by b.planned_at,b.id),'[]'::jsonb)) into result from public.nutrition_elimination_plan_bindings b where b.tenant_id=requested_tenant and b.client_id=requested_client and (b.planned_at>=clock_timestamp()-interval '30 days' or exists(select 1 from public.nutrition_elimination_roots r where r.plan_binding_id=b.id and r.tenant_id=requested_tenant and r.client_id=requested_client));return result;end$$;
create or replace function care_private.read_nutrition_elimination_page(requested_tenant uuid,requested_client uuid,requested_actor uuid,cursor_recorded_at timestamptz,cursor_id uuid,page_size integer)
returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;next_recorded_at timestamptz;next_id uuid;begin perform care_private.nutrition_elimination_actor(requested_tenant,requested_client,requested_actor,false);if page_size<1 or page_size>100 or (cursor_recorded_at is null)<>(cursor_id is null) then raise exception 'Ungültige Seitengröße oder Cursorbindung.' using errcode='22023';end if;with page as(select r.* from public.nutrition_elimination_roots r where r.tenant_id=requested_tenant and r.client_id=requested_client and (cursor_recorded_at is null or (r.created_at,r.id)<(cursor_recorded_at,cursor_id)) order by r.created_at desc,r.id desc limit page_size)select p.created_at,p.id into next_recorded_at,next_id from page p order by p.created_at,p.id limit 1;with page as(select r.* from public.nutrition_elimination_roots r where r.tenant_id=requested_tenant and r.client_id=requested_client and (cursor_recorded_at is null or (r.created_at,r.id)<(cursor_recorded_at,cursor_id)) order by r.created_at desc,r.id desc limit page_size)select jsonb_build_object('rows',coalesce(jsonb_agg(care_private.nutrition_elimination_original(x.id) order by x.created_at desc,x.id desc),'[]'::jsonb),'nextCursorRecordedAt',case when next_recorded_at is null then null else to_char(next_recorded_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') end,'nextCursorId',next_id::text) into result from page x;return result;end$$;

create or replace function care_private.commit_nutrition_elimination_packet(p jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$declare t uuid:=(p->>'tenantId')::uuid;c uuid:=(p->>'clientId')::uuid;actor uuid:=(p->>'actorId')::uuid;req uuid:=(p->>'requestId')::uuid;root_ref uuid;head_ref uuid;event_ref uuid:=gen_random_uuid();expected_revision integer:=(p->>'expectedRevision')::integer;binding public.nutrition_elimination_plan_bindings;prior public.nutrition_elimination_events;name text;actual_time timestamptz:=clock_timestamp();fingerprint text;original jsonb;receipt public.nutrition_elimination_receipts;begin
 perform care_private.nutrition_elimination_actor(t,c,actor,true);perform pg_advisory_xact_lock(hashtextextended(t::text||':'||c::text,0));
 if p->>'schemaVersion'<>'1' or p->>'action' not in('create','revise') or jsonb_typeof(p->'entry')<>'object' or p->'entry'->>'kind' not in('nutrition_assessment','meal_support','drink_protocol','swallowing_support','enteral_nutrition','fluid_balance','continence_support','stool_protocol','catheter_care','stoma_care','tube_observation','weight_followup') or coalesce(p->'entry'->>'planSnapshotSha256','')!~'^sha256:[0-9a-f]{64}$' or jsonb_typeof(p->'sources')<>'object' or jsonb_typeof(p#>'{sources,protocols}') is distinct from 'array' or jsonb_typeof(p#>'{sources,weights}') is distinct from 'array' or jsonb_typeof(p#>'{sources,devices}') is distinct from 'array' or jsonb_typeof(p#>'{sources,tasks}') is distinct from 'array' or jsonb_array_length(p#>'{sources,protocols}')+jsonb_array_length(p#>'{sources,weights}')+jsonb_array_length(p#>'{sources,devices}')+jsonb_array_length(p#>'{sources,tasks}')>2000 or p->'sources'->'assessment'->>'id'<>p->'entry'->>'assessmentId' or p->'entry'->'execution'->>'outcome' not in('planned','offered','performed','partial','refused','not_performed') or p->'entry'->>'lifecycle' not in('open','completed') then raise exception 'Paket ist unvollständig.' using errcode='23514';end if;
 if ((p#>>'{entry,execution,outcome}')='planned') is distinct from ((p#>>'{entry,occurredAt}') is null) or ((p#>>'{entry,decision,state}')='not_asked') is distinct from ((p#>>'{entry,decision,recordedAt}') is null) then raise exception 'Planung, tatsächliches Ereignis oder Personenentscheidung ist zeitlich widersprüchlich.' using errcode='23514';end if;
 if (p#>>'{entry,occurredAt}') is not null then perform (p#>>'{entry,occurredAt}')::timestamptz;end if;if (p#>>'{entry,decision,recordedAt}') is not null then perform (p#>>'{entry,decision,recordedAt}')::timestamptz;end if;
 if p#>>'{entry,decision,state}' not in('not_asked','consented','refused','withdrawn') then raise exception 'Personenentscheidung ist ungültig.' using errcode='23514';end if;
 if p->'entry'->'execution'->>'outcome' in('performed','partial') and (p->'entry'->'decision'->>'state'<>'consented' or jsonb_array_length(coalesce(p->'entry'->'execution'->'performedBy','[]'::jsonb))<1 or btrim(coalesce(p->'entry'->'execution'->>'result',''))='') then raise exception 'Durchführung ist nicht belegt.' using errcode='23514';end if;
 if p->'entry'->>'kind'='fluid_balance' and coalesce((p->'entry'->'elimination'->>'complete')::boolean,false) then raise exception 'Mengenausschnitt darf nicht als klinisch vollständige Bilanz freigegeben werden.' using errcode='23514';end if;
 if p->'entry'->>'kind' in('meal_support','drink_protocol') and (((p#>>'{entry,intake,offered}') is not null or (p#>>'{entry,intake,actual}') is not null) and p#>>'{entry,intake,unit}' not in('g','ml','percent') or ((p#>>'{entry,intake,target}') is null) is distinct from (p#>>'{entry,intake,targetUnit}'='none')) then raise exception 'Aufnahme und individuelles Ziel benötigen ihre Originaleinheiten.' using errcode='23514';end if;
 if (p#>>'{entry,weight,measurementId}') is not null and not exists(select 1 from jsonb_array_elements(p#>'{sources,weights}') w where w->>'id'=p#>>'{entry,weight,measurementId}' and (w->>'value') is not distinct from (p#>>'{entry,weight,value}') and w->>'unit'=p#>>'{entry,weight,unit}' and w->>'conditions'=p#>>'{entry,weight,conditions}') then raise exception 'Gewicht stimmt nicht mit dem Quelloriginal überein.' using errcode='23514';end if;
 if p->'entry'->>'kind' in('catheter_care','stoma_care','tube_observation') and not exists(select 1 from jsonb_array_elements(p#>'{sources,devices}') d where d->>'id'=p#>>'{entry,device,deviceId}' and d->>'type'=case p->'entry'->>'kind' when 'catheter_care' then 'catheter' when 'stoma_care' then 'stoma' else 'tube' end) then raise exception 'Gerät stimmt nicht mit dem Quelloriginal überein.' using errcode='23514';end if;
 if p->'entry'->>'kind'='enteral_nutrition' and not exists(select 1 from jsonb_array_elements(p#>'{sources,devices}') d where d->>'id'=p#>>'{entry,enteral,deviceId}' and d->>'type' in('peg','tube')) then raise exception 'Enteraler Zugang stimmt nicht mit dem Quelloriginal überein.' using errcode='23514';end if;
 if (p#>>'{entry,followUp,taskId}') is not null and not exists(select 1 from jsonb_array_elements(p#>'{sources,tasks}') task where task->>'id'=p#>>'{entry,followUp,taskId}') then raise exception 'Folgeauftrag stimmt nicht mit dem Quelloriginal überein.' using errcode='23514';end if;
 if p->'entry'->>'lifecycle'='completed' and (p->'entry'->'execution'->>'outcome' in('planned','offered') or coalesce((p->'entry'->'followUp'->>'required')::boolean,false) and p->'entry'->'followUp'->>'state'<>'closed') then raise exception 'Abschlussvoraussetzungen fehlen.' using errcode='23514';end if;
 select * into receipt from public.nutrition_elimination_receipts r where r.tenant_id=t and r.request_id=req for update;if found then if receipt.packet<>p or receipt.actor_id<>actor then raise exception 'Anfragekennung ist anders gebunden.' using errcode='40001';end if;return jsonb_build_object('requestId',req::text,'packet',p,'original',receipt.original);end if;
 perform care_private.validate_nutrition_entry(p->'entry',p->'sources');
 select * into binding from public.nutrition_elimination_plan_bindings b where b.tenant_id=t and b.client_id=c and b.plan_version_id=(p->'entry'->>'planVersionId')::uuid and b.measure_id=(p->'entry'->>'measureId')::uuid and b.visit_id=(p->'entry'->>'visitId')::uuid and b.assessment_id=(p->'entry'->>'assessmentId')::uuid and b.kind=p->'entry'->>'kind' for share;
 if not found or binding.plan_snapshot_sha256<>p->'entry'->>'planSnapshotSha256' or binding.source_originals<>p->'sources' then raise exception 'Plan-, Assessment- oder Quelloriginal hat sich geändert.' using errcode='40001';end if;
 if p->>'action'='create' then if expected_revision<>0 or p->'original' is distinct from 'null'::jsonb then raise exception 'Neuanlage enthält fremdes Original.' using errcode='23514';end if;root_ref:=gen_random_uuid();head_ref:=null;insert into public.nutrition_elimination_roots(id,tenant_id,client_id,kind,plan_binding_id,created_at)values(root_ref,t,c,binding.kind,binding.id,actual_time);
 else root_ref:=(p->'original'->>'rootId')::uuid;select * into prior from public.nutrition_elimination_events e where e.root_id=root_ref and e.tenant_id=t and e.client_id=c order by e.revision desc limit 1 for update;if not found or prior.id<>(p->>'expectedHeadId')::uuid or prior.revision<>expected_revision or care_private.nutrition_elimination_original(root_ref)<>p->'original' then raise exception 'Original hat sich geändert.' using errcode='40001';end if;if not exists(select 1 from public.nutrition_elimination_roots r where r.id=root_ref and r.tenant_id=t and r.client_id=c and r.plan_binding_id=binding.id and r.kind=binding.kind) or prior.payload=p->'entry' then raise exception 'Planbindung hat gewechselt oder echte Änderung fehlt.' using errcode='40001';end if;head_ref:=prior.id;if btrim(coalesce(p->>'reason',''))='' then raise exception 'Fortschreibungsgrund fehlt.' using errcode='23514';end if;end if;
 select display_name into name from public.profiles where id=actor and tenant_id=t;if btrim(coalesce(name,''))='' then raise exception 'Akteur ist unvollständig.' using errcode='42501';end if;fingerprint:='sha256:'||encode(extensions.digest(convert_to((p->'entry')::text,'UTF8'),'sha256'),'hex');
 insert into public.nutrition_elimination_events(id,tenant_id,client_id,root_id,revision,previous_id,request_id,actor_id,actor_name,recorded_at,reason,payload,content_fingerprint,packet)values(event_ref,t,c,root_ref,expected_revision+1,head_ref,req,actor,name,actual_time,coalesce(p->>'reason',''),p->'entry',fingerprint,p);original:=care_private.nutrition_elimination_original(root_ref);insert into public.nutrition_elimination_receipts(request_id,tenant_id,client_id,actor_id,root_id,event_id,packet,original,recorded_at)values(req,t,c,actor,root_ref,event_ref,p,original,actual_time);return jsonb_build_object('requestId',req::text,'packet',p,'original',original);end$$;

create or replace function care_private.confirm_nutrition_elimination_packet(requested_tenant uuid,requested_client uuid,requested_actor uuid,requested_request uuid,p jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$declare r public.nutrition_elimination_receipts;begin perform care_private.nutrition_elimination_actor(requested_tenant,requested_client,requested_actor,false);select * into r from public.nutrition_elimination_receipts x where x.request_id=requested_request and x.tenant_id=requested_tenant and x.client_id=requested_client and x.actor_id=requested_actor;if not found or r.packet<>p then raise exception 'Keine unveränderte native Quittung.' using errcode='P0G02';end if;return jsonb_build_object('requestId',r.request_id::text,'packet',r.packet,'original',r.original);end$$;

create or replace function public.web_read_nutrition_elimination_prerequisites(p_tenant_id uuid,p_client_id uuid,p_actor_profile_id uuid)returns jsonb language sql security invoker set search_path='' as $$select care_private.read_nutrition_elimination_prerequisites(p_tenant_id,p_client_id,p_actor_profile_id)$$;
create or replace function public.web_read_nutrition_elimination_page(p_tenant_id uuid,p_client_id uuid,p_actor_profile_id uuid,p_cursor_recorded_at timestamptz,p_cursor_id uuid,p_page_size integer)returns jsonb language sql security invoker set search_path='' as $$select care_private.read_nutrition_elimination_page(p_tenant_id,p_client_id,p_actor_profile_id,p_cursor_recorded_at,p_cursor_id,p_page_size)$$;
create or replace function public.web_commit_nutrition_elimination_packet(p_packet jsonb)returns jsonb language sql security invoker set search_path='' as $$select care_private.commit_nutrition_elimination_packet(p_packet)$$;
create or replace function public.web_confirm_nutrition_elimination_packet(p_tenant_id uuid,p_client_id uuid,p_actor_profile_id uuid,p_request_id uuid,p_packet jsonb)returns jsonb language sql security invoker set search_path='' as $$select care_private.confirm_nutrition_elimination_packet(p_tenant_id,p_client_id,p_actor_profile_id,p_request_id,p_packet)$$;
revoke all on function public.web_read_nutrition_elimination_prerequisites(uuid,uuid,uuid),public.web_read_nutrition_elimination_page(uuid,uuid,uuid,timestamptz,uuid,integer),public.web_commit_nutrition_elimination_packet(jsonb),public.web_confirm_nutrition_elimination_packet(uuid,uuid,uuid,uuid,jsonb) from public,anon;
grant execute on function public.web_read_nutrition_elimination_prerequisites(uuid,uuid,uuid),public.web_read_nutrition_elimination_page(uuid,uuid,uuid,timestamptz,uuid,integer),public.web_commit_nutrition_elimination_packet(jsonb),public.web_confirm_nutrition_elimination_packet(uuid,uuid,uuid,uuid,jsonb) to authenticated;
revoke all on function care_private.nutrition_elimination_actor(uuid,uuid,uuid,boolean),care_private.nutrition_elimination_original(uuid),care_private.read_nutrition_elimination_prerequisites(uuid,uuid,uuid),care_private.read_nutrition_elimination_page(uuid,uuid,uuid,timestamptz,uuid,integer),care_private.commit_nutrition_elimination_packet(jsonb),care_private.confirm_nutrition_elimination_packet(uuid,uuid,uuid,uuid,jsonb) from public,anon,authenticated;
grant execute on function care_private.read_nutrition_elimination_prerequisites(uuid,uuid,uuid),care_private.read_nutrition_elimination_page(uuid,uuid,uuid,timestamptz,uuid,integer),care_private.commit_nutrition_elimination_packet(jsonb),care_private.confirm_nutrition_elimination_packet(uuid,uuid,uuid,uuid,jsonb) to authenticated;
